cd "$env:USERPROFILE\Downloads\smartcalc"
Write-Host "=== Installing HIGH LEVEL WiFi Analyzer ===" -ForegroundColor Cyan
Copy-Item "src\components\wifi\wifi-analyzer.tsx" "src\components\wifi\wifi-analyzer.tsx.bak-geo" -Force -ErrorAction SilentlyContinue
$b64 = ""
$bytes = [System.Convert]::FromBase64String($b64)
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\components\wifi\wifi-analyzer.tsx"), $bytes)
Write-Host "[OK] wifi-analyzer.tsx replaced" -ForegroundColor Green
$apiDir = "src\app\api\wifi\ping"
New-Item -ItemType Directory -Path $apiDir -Force | Out-Null
@'
export const dynamic = "force-dynamic";
export async function GET(req: Request) {
  const url = new URL(req.url);
  const bytes = Number(url.searchParams.get("bytes") || "0");
  if (bytes > 0) {
    const size = Math.min(bytes, 5000000);
    const buf = new Uint8Array(size);
    return new Response(buf, {
      headers: {
        "Content-Type": "application/octet-stream",
        "Cache-Control": "no-store, no-cache, must-revalidate",
        "Content-Length": String(size),
      },
    });
  }
  return Response.json({ ok: true, ts: Date.now() }, { headers: { "Cache-Control": "no-store" } });
}
'@ | Set-Content "$apiDir\route.ts" -Encoding UTF8
Write-Host "[OK] /api/wifi/ping created" -ForegroundColor Green
npx tsc --noEmit
if ($LASTEXITCODE -eq 0) {
  Write-Host "[PASS] TypeScript OK - Starting dev" -ForegroundColor Green
  npm run dev
} else {
  Write-Host "[FAIL] TypeScript errors" -ForegroundColor Red
}
